  `album_id` bigint NOT NULL,
  `media_id` bigint NOT NULL,
  `sort_order` int NOT NULL DEFAULT 0,
  `added_by` bigint NOT NULL,
  `added_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_photo_album_media`(`album_id` ASC, `media_id` ASC) USING BTREE,
  INDEX `idx_photo_album_media_media`(`media_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '相册媒体关系' ROW_FORMAT = Dynamic;

