-- ----------------------------
-- Table structure for photo_media
-- ----------------------------
DROP TABLE IF EXISTS `photo_media`;
CREATE TABLE `photo_media`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `space_id` bigint NOT NULL,
  `uploader_id` bigint NOT NULL,
  `original_file_id` bigint NOT NULL,
  `display_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `relative_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '目录导入相对路径',
  `media_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'IMAGE/VIDEO',
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `favorite` tinyint NOT NULL DEFAULT 0,
  `width` int NULL DEFAULT NULL,
  `height` int NULL DEFAULT NULL,
  `orientation` int NULL DEFAULT NULL,
  `captured_at` datetime NULL DEFAULT NULL,
  `time_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'EXIF/VIDEO/FILE/UPLOAD',
  `latitude` decimal(10, 7) NULL DEFAULT NULL,
  `longitude` decimal(10, 7) NULL DEFAULT NULL,
  `altitude` decimal(10, 2) NULL DEFAULT NULL,
  `location_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `camera_make` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `camera_model` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `lens_model` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `duration_ms` bigint NULL DEFAULT NULL,
  `video_codec` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `audio_codec` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `bit_rate` bigint NULL DEFAULT NULL,
  `frame_rate` decimal(8, 3) NULL DEFAULT NULL,
  `process_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING',
  `process_error` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `metadata_json` json NULL,
  `status` tinyint NOT NULL DEFAULT 1,
  `deleted_at` datetime NULL DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_photo_media_space_file`(`space_id` ASC, `original_file_id` ASC) USING BTREE,
  INDEX `idx_photo_media_timeline`(`space_id` ASC, `status` ASC, `captured_at` ASC, `id` ASC) USING BTREE,
  INDEX `idx_photo_media_type`(`space_id` ASC, `media_type` ASC, `status` ASC, `captured_at` ASC) USING BTREE,
  INDEX `idx_photo_media_uploader`(`uploader_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '照片视频媒体' ROW_FORMAT = Dynamic;

