DROP TABLE IF EXISTS `photo_space`;
CREATE TABLE `photo_space`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '空间名称',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PERSONAL' COMMENT 'PERSONAL/FAMILY',
  `owner_id` bigint NOT NULL COMMENT '空间所有者',
  `cover_media_id` bigint NULL DEFAULT NULL COMMENT '封面媒体ID',
  `quota_bytes` bigint NULL DEFAULT NULL COMMENT '容量上限',
  `used_bytes` bigint NOT NULL DEFAULT 0 COMMENT '已用容量缓存',
  `status` tinyint NOT NULL DEFAULT 1,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_photo_space_owner_type`(`owner_id` ASC, `type` ASC) USING BTREE,
  INDEX `idx_photo_space_owner`(`owner_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '相册空间' ROW_FORMAT = Dynamic;

