-- ----------------------------
-- Table structure for sys_user_org_post
-- ----------------------------
DROP TABLE IF EXISTS `sys_user_org_post`;
CREATE TABLE `sys_user_org_post`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `dept_id` bigint NOT NULL COMMENT '部门ID',
  `post_id` bigint NOT NULL COMMENT '岗位ID',
  `is_primary` tinyint NOT NULL DEFAULT 0 COMMENT '是否主任职: 1-是 0-否',
  `job_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'main' COMMENT '任职类型: main/part_time/temporary/agent/project',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 1-启用 0-停用',
  `start_time` datetime NULL DEFAULT NULL COMMENT '任职开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '任职结束时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_primary`(`user_id` ASC, `dept_id` ASC, `post_id` ASC, `job_type` ASC) USING BTREE,
  INDEX `idx_uop_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_uop_dept`(`dept_id` ASC) USING BTREE,
  INDEX `idx_uop_post`(`post_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1017 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户任职关系表' ROW_FORMAT = DYNAMIC;

